"use client"

/**
 * map-browser · a filterable list and a map that stay in sync.
 *
 * Behavior reference: PropXYZ "Map Browser" (public post 2121215251761016832).
 * Clean-room: no PropXYZ code, data, icons or assets were copied. The map
 * surface is adapted from MapCN (MIT License · Copyright (c) 2025 Anmoldeep
 * Singh) through registry/ui/geo-map.tsx. maplibre-gl is BSD-3-Clause.
 *
 * The list is the accessible source. The map repeats it. Filtering lives in
 * the host: pass the filtered `places` and the unfiltered `total`.
 */

import { useCallback, useEffect, useId, useMemo, useRef, useState, type ReactNode, type RefObject } from "react"
import { AnimatePresence, motion } from "motion/react"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { BottomSheet } from "@/components/ui/bottom-sheet"
import { EmptyState } from "@/components/ui/empty-state"
import { GeoMap } from "@/components/ui/geo-map"
import { motionPresets } from "@/lib/motion"
import {
  assertProvider,
  resolveMapBrowserLabels,
  shouldCluster,
  usePrefersReducedMotion,
  viewState,
  type MapBrowserLabels,
  type MapCategory,
  type MapClusterOption,
  type MapPlace,
  type MapProvider,
  type MapStatus,
  type MapTone,
} from "@/lib/map-browser"

export * from "@/lib/map-browser"

export type MapBrowserClassNames = {
  root?: string
  toolbar?: string
  body?: string
  list?: string
  card?: string
  map?: string
  pin?: string
  cluster?: string
  detail?: string
}

export type MapCardState = { active: boolean; selected: boolean }

export type MapBrowserProps<TMeta = unknown> = {
  /** Already filtered by the host. */
  places: readonly MapPlace<TMeta>[]
  /** Count before filtering. Tells empty (0) from nomatch. */
  total: number
  status?: MapStatus
  provider: MapProvider
  categories?: readonly MapCategory[]
  /** Usually a host-controlled FilterToolbar. */
  toolbar?: ReactNode
  selectedId?: string | null
  defaultSelectedId?: string | null
  onSelectedChange?: (id: string | null) => void
  renderCard?: (place: MapPlace<TMeta>, state: MapCardState) => ReactNode
  renderDetail?: (place: MapPlace<TMeta>) => ReactNode
  /** On by default above 50 places. */
  cluster?: MapClusterOption
  onRetry?: () => void
  onClearFilters?: () => void
  /** es-MX by default. Pass mapBrowserLabelsEn for English. */
  labels?: Partial<MapBrowserLabels>
  className?: string
  classNames?: MapBrowserClassNames
}

const toneDot: Record<MapTone, string> = {
  "chart-1": "bg-chart-1",
  "chart-2": "bg-chart-2",
  "chart-3": "bg-chart-3",
  "chart-4": "bg-chart-4",
  "chart-5": "bg-chart-5",
}

export function MapBrowser<TMeta = unknown>({
  places,
  total,
  status = "ready",
  provider,
  categories,
  toolbar,
  selectedId: selectedProp,
  defaultSelectedId = null,
  onSelectedChange,
  renderCard,
  renderDetail,
  cluster,
  onRetry,
  onClearFilters,
  labels: labelsProp,
  className,
  classNames,
}: MapBrowserProps<TMeta>) {
  assertProvider(provider)
  const labels = useMemo(() => resolveMapBrowserLabels(labelsProp), [labelsProp])
  const reduced = usePrefersReducedMotion()
  const rootRef = useRef<HTMLElement>(null)
  const compact = useCompactContainer(rootRef)
  // Side panel width (25rem) plus its inset, in px at the default root size.
  const detailInset = 412
  const titleId = useId()
  const detailTitleId = useId()

  const [selectedState, setSelectedState] = useState<string | null>(defaultSelectedId)
  const controlled = selectedProp !== undefined
  const selectedRaw = controlled ? selectedProp : selectedState
  const byId = useMemo(() => new Map(places.map((place) => [place.id, place])), [places])
  const selectedId = selectedRaw && byId.has(selectedRaw) ? selectedRaw : null
  const selected = selectedId ? byId.get(selectedId) : undefined
  const [activeId, setActiveId] = useState<string | null>(null)
  const categoryById = useMemo(() => new Map((categories ?? []).map((c) => [c.id, c])), [categories])

  const state = viewState({ places, total, status })
  const clusterOn = shouldCluster(cluster, places.length)
  const clusterOptions = typeof cluster === "object" ? cluster : {}

  const [announcement, setAnnouncement] = useState("")
  const originRef = useRef<HTMLElement | null>(null)
  const cardRefs = useRef(new Map<string, HTMLButtonElement>())

  const select = useCallback(
    (id: string | null) => {
      if (id !== null && typeof document !== "undefined") {
        const focused = document.activeElement
        if (focused instanceof HTMLElement && focused !== document.body) originRef.current = focused
      }
      if (!controlled) setSelectedState(id)
      const place = id ? byId.get(id) : undefined
      if (place) setAnnouncement(labels.selected(place.title))
      onSelectedChange?.(id)
    },
    [byId, controlled, labels, onSelectedChange],
  )

  const close = useCallback(() => {
    const origin = originRef.current
    select(null)
    if (origin && origin.isConnected) requestAnimationFrame(() => origin.focus())
    else if (origin) {
      const id = origin.closest<HTMLElement>("[data-place-id]")?.dataset.placeId
      if (id) cardRefs.current.get(id)?.focus()
    }
  }, [select])

  // Keep the selected card in view when the map picks it.
  useEffect(() => {
    if (!selectedId) return
    cardRefs.current.get(selectedId)?.scrollIntoView({ block: "nearest", behavior: reduced ? "auto" : "smooth" })
  }, [reduced, selectedId])

  // One polite announcement after the count settles (300 ms), never on mount.
  const firstCount = useRef(true)
  useEffect(() => {
    if (firstCount.current) {
      firstCount.current = false
      return
    }
    if (state === "loading") return
    const timer = setTimeout(() => setAnnouncement(labels.count(places.length)), 300)
    return () => clearTimeout(timer)
  }, [labels, places.length, state])

  const detail = selected
    ? renderDetail?.(selected) ?? <DefaultDetail place={selected} category={selected.category ? categoryById.get(selected.category) : undefined} />
    : null

  return (
    <section
      ref={rootRef}
      data-slot="map-browser"
      data-state={state}
      data-layout={compact ? "stacked" : "split"}
      aria-labelledby={titleId}
      onKeyDown={(event) => {
        // Escape closes the side panel from anywhere in the piece. The sheet handles its own.
        if (event.key === "Escape" && selected && !compact && !event.defaultPrevented) {
          event.stopPropagation()
          close()
        }
      }}
      className={cn("@container/map-browser flex h-full min-h-[34rem] min-w-0 flex-col gap-3", className, classNames?.root)}
    >
      {toolbar ? (
        <div data-slot="map-browser-toolbar" className={cn("min-w-0", classNames?.toolbar)}>
          {toolbar}
        </div>
      ) : null}

      <div
        data-slot="map-browser-body"
        className={cn(
          "grid min-h-0 flex-1 gap-3",
          "grid-cols-[minmax(0,1fr)] grid-rows-[minmax(14rem,42%)_minmax(0,1fr)] @3xl/map-browser:grid-cols-[minmax(18rem,24rem)_minmax(0,1fr)] @3xl/map-browser:grid-rows-1",
          classNames?.body,
        )}
      >
        <div
          data-slot="map-browser-list"
          className={cn("order-2 flex min-h-0 flex-col rounded-xl border bg-card text-card-foreground @3xl/map-browser:order-1", classNames?.list)}
        >
          <h2 id={titleId} className="shrink-0 border-b px-4 py-3 text-sm font-medium tabular-nums">
            {state === "loading" ? <span>{labels.loading}</span> : labels.count(places.length)}
          </h2>
          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain">
            {state === "loading" ? (
              <ul aria-busy="true" aria-label={labels.loading} className="flex flex-col gap-2 p-3">
                {Array.from({ length: 5 }, (_, i) => (
                  <li key={i} aria-hidden className="flex flex-col gap-2 rounded-lg border p-3">
                    <Skeleton className="h-4 w-2/3" />
                    <Skeleton className="h-3 w-1/3" />
                  </li>
                ))}
              </ul>
            ) : state === "error" ? (
              <EmptyState
                title={labels.errorTitle}
                description={labels.errorDescription}
                action={onRetry ? <Button type="button" variant="outline" size="sm" onClick={onRetry}>{labels.retry}</Button> : undefined}
                className="m-3"
              />
            ) : state === "empty" ? (
              <EmptyState title={labels.emptyTitle} description={labels.emptyDescription} className="m-3" />
            ) : state === "nomatch" ? (
              <EmptyState
                title={labels.nomatchTitle}
                description={labels.nomatchDescription}
                action={
                  onClearFilters ? (
                    <Button type="button" variant="outline" size="sm" onClick={onClearFilters}>
                      {labels.clearFilters}
                    </Button>
                  ) : undefined
                }
                className="m-3"
              />
            ) : (
              <ul aria-label={labels.list} className="flex flex-col gap-2 p-3">
                {places.map((place) => {
                  const category = place.category ? categoryById.get(place.category) : undefined
                  const cardState = { active: activeId === place.id, selected: selectedId === place.id }
                  return (
                    <li key={place.id} className="min-w-0">
                      <button
                        ref={(node) => {
                          if (node) cardRefs.current.set(place.id, node)
                          else cardRefs.current.delete(place.id)
                        }}
                        type="button"
                        data-slot="map-browser-card"
                        data-place-id={place.id}
                        data-active={cardState.active ? "true" : "false"}
                        data-selected={cardState.selected ? "true" : "false"}
                        aria-current={cardState.selected ? "true" : undefined}
                        onPointerEnter={() => setActiveId(place.id)}
                        onPointerLeave={() => setActiveId(null)}
                        onFocus={() => setActiveId(place.id)}
                        onBlur={() => setActiveId(null)}
                        onClick={() => select(place.id)}
                        className={cn(
                          "w-full min-w-0 rounded-lg border bg-background p-3 text-left outline-none",
                          "hover:bg-accent data-[active=true]:bg-accent data-[selected=true]:border-primary data-[selected=true]:ring-1 data-[selected=true]:ring-primary",
                          "focus-visible:ring-[3px] focus-visible:ring-ring/50",
                          classNames?.card,
                        )}
                      >
                        {renderCard ? (
                          renderCard(place, cardState)
                        ) : (
                          <DefaultCard place={place} category={category} />
                        )}
                      </button>
                    </li>
                  )
                })}
              </ul>
            )}
          </div>
        </div>

        <div
          data-slot="map-browser-map"
          className={cn("relative order-1 min-h-0 overflow-hidden rounded-xl border @3xl/map-browser:order-2", classNames?.map)}
        >
          <GeoMap
            provider={provider}
            places={state === "ready" ? places : []}
            categories={categories}
            activeId={activeId}
            selectedId={selectedId}
            onActivate={setActiveId}
            onSelect={select}
            cluster={clusterOn}
            clusterRadius={clusterOptions.radius}
            clusterMinPoints={clusterOptions.minPoints}
            labels={labels}
            reducedMotion={reduced}
            dimmed={state === "error"}
            revealInset={selected && !compact ? detailInset : 0}
            classNames={{ pin: classNames?.pin, cluster: classNames?.cluster }}
          />

          <AnimatePresence initial={false}>
            {selected && !compact ? (
              <motion.aside
                key="detail"
                aria-labelledby={detailTitleId}
                data-slot="map-browser-detail"
                initial={reduced ? { opacity: 0 } : { opacity: 0, x: 16 }}
                animate={{ opacity: 1, x: 0 }}
                exit={reduced ? { opacity: 0 } : { opacity: 0, x: 16 }}
                transition={reduced ? { duration: 0 } : { duration: motionPresets.duration.standard, ease: motionPresets.ease.enter }}
                className={cn(
                  "absolute left-3 top-3 z-20 flex max-h-[calc(100%-3.5rem)] w-[min(25rem,calc(100%-4.5rem))] flex-col overflow-hidden rounded-xl border bg-popover text-popover-foreground shadow-lg",
                  classNames?.detail,
                )}
              >
                <div className="flex items-start justify-between gap-2 border-b px-4 py-3">
                  <h3 id={detailTitleId} className="min-w-0 break-words text-base font-medium">
                    {selected.title}
                  </h3>
                  <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.close} onClick={close} className="-mr-1 shrink-0">
                    <X aria-hidden />
                  </Button>
                </div>
                <div className="min-h-0 flex-1 overflow-y-auto p-4">{detail}</div>
              </motion.aside>
            ) : null}
          </AnimatePresence>
        </div>
      </div>

      {compact ? (
        <BottomSheet
          open={Boolean(selected)}
          onOpenChange={(open) => {
            if (!open) close()
          }}
          title={selected?.title ?? labels.detail}
          detents={[0.5, 0.92]}
          closeLabel={labels.close}
        >
          {detail}
        </BottomSheet>
      ) : null}

      <p data-slot="map-browser-status" role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </section>
  )
}

/** Stacked layout and the bottom sheet below 48rem of the piece's own width. Unmeasured (SSR, jsdom) counts as wide. */
function useCompactContainer(ref: RefObject<HTMLElement | null>) {
  const [compact, setCompact] = useState(false)
  useEffect(() => {
    const node = ref.current
    if (!node || typeof ResizeObserver === "undefined") return
    const measure = () => {
      const width = node.getBoundingClientRect().width
      setCompact(width > 0 && width < 768)
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(node)
    return () => observer.disconnect()
  }, [ref])
  return compact
}

function CategoryBadge({ category }: { category: MapCategory }) {
  return (
    <span className="inline-flex max-w-full items-center gap-1.5 rounded-full border px-2 py-0.5 text-xs text-muted-foreground">
      <span aria-hidden className={cn("size-2 shrink-0 rounded-full bg-foreground", category.tone && toneDot[category.tone])} />
      <span className="truncate">{category.label}</span>
    </span>
  )
}

function DefaultCard({ place, category }: { place: MapPlace<unknown>; category?: MapCategory }) {
  return (
    <span className="flex min-w-0 flex-col gap-1">
      <span className="break-words text-sm font-medium [overflow-wrap:anywhere]">{place.title}</span>
      {place.subtitle ? <span className="break-words text-xs text-muted-foreground [overflow-wrap:anywhere]">{place.subtitle}</span> : null}
      {category ? (
        <span className="mt-1 flex">
          <CategoryBadge category={category} />
        </span>
      ) : null}
    </span>
  )
}

function DefaultDetail({ place, category }: { place: MapPlace<unknown>; category?: MapCategory }) {
  return (
    <div className="flex flex-col gap-3 text-sm">
      {place.subtitle ? <p className="text-muted-foreground [overflow-wrap:anywhere]">{place.subtitle}</p> : null}
      {category ? (
        <span className="flex">
          <CategoryBadge category={category} />
        </span>
      ) : null}
    </div>
  )
}

"use client"

/**
 * geo-map · internal map surface for map-browser. Not a registry item of its own.
 *
 * Adapted from MapCN by Anmoldeep Singh (MIT License · Copyright (c) 2025
 * Anmoldeep Singh, https://github.com/AnmolSaini16/mapcn, pin b243a4d3). Kept:
 * the client-only maplibre instance owned by one component and DOM markers
 * rendered through React portals. Changed: no CSS import (the host loads the
 * maplibre stylesheet), no worker CDN (the host passes provider.workerUrl), no
 * compact attribution (the provider credit is always expanded), no color
 * literals (canvas paint comes from host tokens), clusters from the native
 * GeoJSON source drawn as accessible DOM buttons.
 *
 * maplibre-gl is BSD-3-Clause, Copyright (c) 2023, MapLibre contributors.
 */

import { useEffect, useEffectEvent, useId, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from "react"
import { createPortal } from "react-dom"
import type {
  GeoJSONSource,
  GeoJSONSourceSpecification,
  Map as MaplibreMap,
  StyleSpecification,
} from "maplibre-gl"
import { Minus, Plus, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import {
  boundsOf,
  markersFrom,
  toFeatureCollection,
  tokenColor,
  useDocumentTheme,
  type MapBrowserLabels,
  type MapCategory,
  type MapMarker,
  type MapPlace,
  type MapProvider,
  type MapStyle,
  type MapTone,
  type PlaceFeature,
} from "@/lib/map-browser"

export const GEO_MAP_SOURCE = "map-browser-places"
const HIT_LAYER = "map-browser-places-hit"

export type GeoMapState = "loading" | "moving" | "idle" | "error"

export type GeoMapClassNames = {
  root?: string
  pin?: string
  cluster?: string
  controls?: string
  attribution?: string
  fallback?: string
}

export type GeoMapProps = {
  provider: MapProvider
  places: readonly MapPlace[]
  categories?: readonly MapCategory[]
  activeId: string | null
  selectedId: string | null
  onActivate: (id: string | null) => void
  onSelect: (id: string) => void
  cluster: boolean
  clusterRadius?: number
  clusterMinPoints?: number
  labels: MapBrowserLabels
  reducedMotion: boolean
  /** Dims the canvas, for the data error state. */
  dimmed?: boolean
  /** Pixels covered at the inline start by a panel. A selected pin under it is eased into view. */
  revealInset?: number
  className?: string
  classNames?: GeoMapClassNames
}

type MaplibreModule = typeof import("maplibre-gl")
type GeoJSONData = Extract<GeoJSONSourceSpecification["data"], object>

let maplibreModule: Promise<MaplibreModule> | null = null

/** Loads maplibre-gl once, on the client, the first time a map mounts. */
function loadMaplibre(): Promise<MaplibreModule> {
  maplibreModule ??= import("maplibre-gl").then(
    (mod) => ((mod as { default?: MaplibreModule }).default ?? mod) as MaplibreModule,
  )
  return maplibreModule
}

const toneDot: Record<MapTone, string> = {
  "chart-1": "bg-chart-1",
  "chart-2": "bg-chart-2",
  "chart-3": "bg-chart-3",
  "chart-4": "bg-chart-4",
  "chart-5": "bg-chart-5",
}

const NAV_KEYS = new Set(["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp", "Home", "End"])

function resolveStyle(style: MapStyle, token: (name: string) => string): StyleSpecification | string {
  return typeof style === "function" ? style(token) : style
}

type Engine = { lib: MaplibreModule; map: MaplibreMap }

/** One maplibre Marker whose element React fills through a portal. */
function MarkerPortal({
  engine,
  marker,
  onNavigate,
  children,
}: {
  engine: Engine
  marker: MapMarker
  onNavigate: (key: string, event: KeyboardEvent) => void
  children: ReactNode
}) {
  const [element] = useState(() => {
    const el = document.createElement("div")
    el.dataset.slot = "map-marker"
    el.dataset.markerKey = marker.key
    return el
  })
  const navigate = useEffectEvent((event: KeyboardEvent) => onNavigate(marker.key, event))

  useLayoutEffect(() => {
    // Native listener: maplibre pans on arrow keys from the canvas container,
    // so the pin handles them first and stops them there.
    const onKeyDown = (event: KeyboardEvent) => navigate(event)
    element.addEventListener("keydown", onKeyDown)
    const instance = new engine.lib.Marker({ element, anchor: "center" }).setLngLat([marker.lng, marker.lat]).addTo(engine.map)
    return () => {
      element.removeEventListener("keydown", onKeyDown)
      instance.remove()
    }
  }, [element, engine, marker.lat, marker.lng])

  return createPortal(children, element)
}

export function GeoMap({
  provider,
  places,
  categories,
  activeId,
  selectedId,
  onActivate,
  onSelect,
  cluster,
  clusterRadius = 50,
  clusterMinPoints = 2,
  labels,
  reducedMotion,
  dimmed = false,
  revealInset = 0,
  className,
  classNames,
}: GeoMapProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const engineRef = useRef<Engine | null>(null)
  const [engine, setEngine] = useState<Engine | null>(null)
  const [state, setState] = useState<GeoMapState>("loading")
  const [clustered, setClustered] = useState<MapMarker[]>([])
  const [rovingKey, setRovingKey] = useState<string | null>(null)
  const theme = useDocumentTheme()
  const hintId = useId()

  const order = useMemo(() => places.map((place) => place.id), [places])
  const byId = useMemo(() => new Map(places.map((place) => [place.id, place])), [places])
  const categoryById = useMemo(() => new Map((categories ?? []).map((c) => [c.id, c])), [categories])

  const markers: MapMarker[] = useMemo(() => {
    if (cluster) return clustered
    return places.map((place) => ({
      kind: "place" as const,
      key: `place-${place.id}`,
      id: place.id,
      lng: place.position.lng,
      lat: place.position.lat,
    }))
  }, [cluster, clustered, places])

  const token = (name: string) => tokenColor(name, containerRef.current)
  const styleFor = (mode: "light" | "dark") =>
    resolveStyle((mode === "dark" && provider.styles.dark) || provider.styles.light, token)

  const installPlaces = useEffectEvent((map: MaplibreMap) => {
    if (map.getLayer(HIT_LAYER)) map.removeLayer(HIT_LAYER)
    if (map.getSource(GEO_MAP_SOURCE)) map.removeSource(GEO_MAP_SOURCE)
    map.addSource(GEO_MAP_SOURCE, {
      type: "geojson",
      data: toFeatureCollection(places) as GeoJSONData,
      cluster,
      clusterRadius,
      clusterMinPoints,
      clusterMaxZoom: (provider.maxZoom ?? 18) - 1,
    })
    // Invisible layer so the source loads tiles. Its paint still comes from a token.
    map.addLayer({
      id: HIT_LAYER,
      type: "circle",
      source: GEO_MAP_SOURCE,
      paint: { "circle-radius": 1, "circle-opacity": 0, "circle-color": tokenColor("--primary", containerRef.current) },
    })
  })

  const refreshClusters = useEffectEvent((map: MaplibreMap) => {
    if (!cluster) return
    const features = map.querySourceFeatures(GEO_MAP_SOURCE) as unknown as PlaceFeature[]
    setClustered(markersFrom(features, order))
  })

  const createMap = useEffectEvent((lib: MaplibreModule, container: HTMLDivElement): MaplibreMap | null => {
    if (provider.workerUrl && lib.getWorkerUrl?.() !== provider.workerUrl) lib.setWorkerUrl(provider.workerUrl)
    const bounds = boundsOf(places)
    try {
      return new lib.Map({
        container,
        style: styleFor(document.documentElement.classList.contains("dark") ? "dark" : "light"),
        attributionControl: false,
        dragRotate: false,
        pitchWithRotate: false,
        touchPitch: false,
        maxZoom: provider.maxZoom ?? 18,
        ...(bounds
          ? { bounds, fitBoundsOptions: { padding: 48, maxZoom: 14 } }
          : { center: [0, 20] as [number, number], zoom: 1.5 }),
        locale: { "Map.Title": labels.mapCanvas },
      })
    } catch {
      return null
    }
  })

  const fitAll = useEffectEvent((map: MaplibreMap, duration: number) => {
    const bounds = boundsOf(places)
    if (bounds) map.fitBounds(bounds, { padding: 48, maxZoom: 14, duration })
  })

  // Create the map once, on the client only.
  useEffect(() => {
    const container = containerRef.current
    if (!container) return
    let cancelled = false
    let map: MaplibreMap | null = null
    let loaded = false
    loadMaplibre()
      .then((lib) => {
        if (cancelled) return
        map = createMap(lib, container)
        if (!map) {
          setState("error")
          return
        }
        const ready = map
        const group = ready.getCanvasContainer?.()
        if (group) {
          group.setAttribute("role", "group")
          group.setAttribute("aria-label", labels.pins)
        }
        ready.on("load", () => {
          loaded = true
          ready.resize()
          fitAll(ready, 0)
          installPlaces(ready)
          engineRef.current = { lib, map: ready }
          setEngine(engineRef.current)
        })
        ready.on("style.load", () => {
          if (loaded) installPlaces(ready)
        })
        ready.on("movestart", () => setState((s) => (s === "error" ? s : "moving")))
        ready.on("idle", () => {
          setState((s) => (s === "error" ? s : "idle"))
          refreshClusters(ready)
        })
        ready.on("error", () => {
          if (!loaded) setState("error")
        })
      })
      .catch(() => {
        if (!cancelled) setState("error")
      })
    // Keep the canvas sized to its box: the piece can mount inside a sheet, a
    // tab or a scaled thumbnail.
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(() => map?.resize())
    observer?.observe(container)
    return () => {
      cancelled = true
      observer?.disconnect()
      engineRef.current = null
      map?.remove()
    }
    // The map is created once. Later prop changes go through the effects below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Theme: rebuild the style so canvas colors follow the host tokens.
  const applyTheme = useEffectEvent((map: MaplibreMap, mode: "light" | "dark") => {
    if (!provider.styles.dark && typeof provider.styles.light !== "function") return
    map.setStyle(styleFor(mode), { diff: false })
  })
  const themed = useRef<string | null>(null)
  useEffect(() => {
    if (!engine) return
    if (themed.current === null) {
      themed.current = theme
      return
    }
    if (themed.current === theme) return
    themed.current = theme
    applyTheme(engine.map, theme)
  }, [engine, theme])

  // Data and cluster mode.
  const shape = useRef<{ ids: string; cluster: boolean } | null>(null)
  const syncData = useEffectEvent((map: MaplibreMap) => {
    const ids = order.join("|")
    const previous = shape.current
    shape.current = { ids, cluster }
    if (!previous) return
    if (previous.cluster !== cluster) installPlaces(map)
    else if (previous.ids !== ids)
      (map.getSource(GEO_MAP_SOURCE) as GeoJSONSource | undefined)?.setData(toFeatureCollection(places) as GeoJSONData)
    if (previous.ids !== ids) fitAll(map, reducedMotion ? 0 : 400)
  })
  useEffect(() => {
    if (engine) syncData(engine.map)
  }, [engine, order, cluster])

  // Bring the selected place into view when it is off screen.
  const reveal = useEffectEvent((map: MaplibreMap, id: string) => {
    const place = byId.get(id)
    if (!place) return
    const point: [number, number] = [place.position.lng, place.position.lat]
    const duration = reducedMotion ? 0 : 400
    const box = containerRef.current
    if (typeof map.project === "function" && box) {
      const { x, y } = map.project(point)
      const edge = 24
      const hidden = x < revealInset + edge || x > box.clientWidth - edge || y < edge || y > box.clientHeight - edge
      if (hidden) map.easeTo({ center: point, offset: [revealInset / 2, 0], duration })
      return
    }
    if (!map.getBounds().contains(point)) map.easeTo({ center: point, duration })
  })
  useEffect(() => {
    if (engine && selectedId) reveal(engine.map, selectedId)
  }, [engine, selectedId])

  const roving = markers.some((marker) => marker.key === rovingKey) ? rovingKey : (markers[0]?.key ?? null)

  const navigate = (key: string, event: KeyboardEvent) => {
    if (event.key === "+" || event.key === "-" || event.key === "=") {
      event.stopPropagation()
      return
    }
    if (!NAV_KEYS.has(event.key)) return
    const index = markers.findIndex((marker) => marker.key === key)
    if (index < 0) return
    const last = markers.length - 1
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? last
          : event.key === "ArrowRight" || event.key === "ArrowDown"
            ? (index + 1) % markers.length
            : (index - 1 + markers.length) % markers.length
    event.preventDefault()
    event.stopPropagation()
    const target = markers[next]
    setRovingKey(target.key)
    containerRef.current
      ?.querySelector<HTMLButtonElement>(`[data-marker-key="${CSS.escape(target.key)}"] button`)
      ?.focus()
  }

  const zoomToCluster = (marker: Extract<MapMarker, { kind: "cluster" }>) => {
    const current = engineRef.current
    const source = current?.map.getSource(GEO_MAP_SOURCE) as GeoJSONSource | undefined
    if (!current || !source) return
    void Promise.resolve(source.getClusterExpansionZoom(marker.clusterId)).then((zoom) => {
      current.map.easeTo({ center: [marker.lng, marker.lat], zoom, duration: reducedMotion ? 0 : 400 })
    })
  }

  const zoom = (direction: 1 | -1) => {
    const map = engineRef.current?.map
    if (!map) return
    const options = reducedMotion ? { duration: 0 } : undefined
    if (direction > 0) map.zoomIn(options)
    else map.zoomOut(options)
  }

  const failed = state === "error"

  return (
    <div
      role="region"
      aria-label={labels.map}
      aria-describedby={hintId}
      data-slot="geo-map"
      data-map-state={state}
      className={cn("relative isolate h-full min-h-48 overflow-hidden bg-muted", className, classNames?.root)}
    >
      <p id={hintId} className="sr-only">
        {labels.mapHint(places.length)}
      </p>
      <div
        ref={containerRef}
        data-slot="geo-map-canvas"
        className={cn(
          "absolute inset-0 transition-opacity duration-200 ease-out motion-reduce:transition-none",
          (dimmed || failed) && "opacity-40",
          state === "loading" && "opacity-0",
        )}
      />
      {state === "loading" ? <Skeleton aria-hidden data-slot="geo-map-skeleton" className="absolute inset-0 rounded-none" /> : null}

      {failed ? (
        <div data-slot="geo-map-fallback" className={cn("absolute inset-0 z-10 grid place-items-center p-6 text-center", classNames?.fallback)}>
          <p className="flex max-w-xs items-start gap-2 rounded-md border bg-background px-3 py-2 text-sm text-foreground shadow-sm">
            <TriangleAlert aria-hidden className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
            <span>{labels.mapError}</span>
          </p>
        </div>
      ) : null}

      <div
        data-slot="geo-map-controls"
        className={cn("absolute right-2 top-2 z-10 flex flex-col overflow-hidden rounded-md border bg-background shadow-sm", classNames?.controls)}
      >
        <Button type="button" variant="ghost" size="icon" aria-label={labels.zoomIn} disabled={failed} onClick={() => zoom(1)} className="rounded-none">
          <Plus aria-hidden />
        </Button>
        <span aria-hidden className="h-px bg-border" />
        <Button type="button" variant="ghost" size="icon" aria-label={labels.zoomOut} disabled={failed} onClick={() => zoom(-1)} className="rounded-none">
          <Minus aria-hidden />
        </Button>
      </div>

      <p
        data-slot="geo-map-attribution"
        className={cn(
          "absolute bottom-0 right-0 z-10 max-w-full rounded-tl-md bg-background px-2 py-0.5 text-xs leading-5 text-foreground",
          classNames?.attribution,
        )}
      >
        {provider.attribution}
      </p>

      {engine && !failed
        ? markers.map((marker) => {
            const tabIndex = marker.key === roving ? 0 : -1
            if (marker.kind === "cluster") {
              return (
                <MarkerPortal key={marker.key} engine={engine} marker={marker} onNavigate={navigate}>
                  <button
                    type="button"
                    data-slot="map-cluster"
                    aria-label={labels.cluster(marker.count)}
                    tabIndex={tabIndex}
                    onFocus={() => setRovingKey(marker.key)}
                    onClick={() => zoomToCluster(marker)}
                    className={cn(
                      "grid h-9 min-w-9 place-items-center rounded-full border-2 border-background bg-primary px-2 text-xs font-medium tabular-nums text-primary-foreground shadow-sm outline-none",
                      "transition-transform duration-150 ease-out hover:-translate-y-0.5 focus-visible:ring-[3px] focus-visible:ring-ring/50 motion-reduce:transition-none motion-reduce:hover:translate-y-0",
                      classNames?.cluster,
                    )}
                  >
                    <span aria-hidden>{marker.count.toLocaleString()}</span>
                  </button>
                </MarkerPortal>
              )
            }
            const place = byId.get(marker.id)
            if (!place) return null
            const category = place.category ? categoryById.get(place.category) : undefined
            const active = activeId === place.id
            const selected = selectedId === place.id
            return (
              <MarkerPortal key={marker.key} engine={engine} marker={marker} onNavigate={navigate}>
                <button
                  type="button"
                  data-slot="map-pin"
                  data-place-id={place.id}
                  data-active={active ? "true" : "false"}
                  data-selected={selected ? "true" : "false"}
                  aria-label={labels.pin(place.title, category?.label)}
                  aria-pressed={selected}
                  tabIndex={tabIndex}
                  onPointerEnter={() => onActivate(place.id)}
                  onPointerLeave={() => onActivate(null)}
                  onFocus={() => {
                    setRovingKey(marker.key)
                    onActivate(place.id)
                  }}
                  onBlur={() => onActivate(null)}
                  onClick={(event) => {
                    setRovingKey(marker.key)
                    event.currentTarget.focus()
                    onSelect(place.id)
                  }}
                  className={cn(
                    "grid size-7 place-items-center rounded-full border-2 border-background bg-foreground shadow-sm outline-none",
                    "transition-transform duration-150 ease-out motion-reduce:transition-none",
                    "data-[active=true]:-translate-y-1 motion-reduce:data-[active=true]:translate-y-0",
                    "data-[active=true]:ring-2 data-[active=true]:ring-ring data-[selected=true]:bg-primary data-[selected=true]:ring-2 data-[selected=true]:ring-ring data-[selected=true]:ring-offset-2 data-[selected=true]:ring-offset-background",
                    "focus-visible:ring-[3px] focus-visible:ring-ring/50",
                    classNames?.pin,
                  )}
                >
                  <span aria-hidden className={cn("size-2.5 rounded-full bg-background", category?.tone && toneDot[category.tone])} />
                </button>
              </MarkerPortal>
            )
          })
        : null}
    </div>
  )
}

// map-browser · pure helpers, types and copy. The only DOM code is
// `tokenColor` and the media-query hooks, and they guard for SSR.
import { useEffect, useState, type ReactNode } from "react"
import type { StyleSpecification } from "maplibre-gl"

export type GeoPoint = { lng: number; lat: number }
export type MapTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5"

export type MapPlace<TMeta = unknown> = {
  id: string
  title: string
  /** "Ciudad, país", an address, a short line. */
  subtitle?: string
  position: GeoPoint
  /** Id of a MapCategory. */
  category?: string
  /** Opaque to the piece. The host reads it in renderCard / renderDetail. */
  meta?: TMeta
}

export type MapCategory = {
  id: string
  label: string
  /** A host chart token. Never a color. */
  tone?: MapTone
  icon?: ReactNode
}

/**
 * A style URL, a style object, or a factory that builds the style from host
 * tokens. The factory gets `token("--background")` and returns a style whose
 * canvas colors come from the theme, so the piece carries no literals.
 */
export type MapStyle =
  | string
  | StyleSpecification
  | ((token: (name: string) => string) => StyleSpecification | string)

export type MapProvider = {
  styles: { light: MapStyle; dark?: MapStyle }
  /** Required. Shown expanded, never collapsed. Plain text. */
  attribution: string
  /** Self-hosted maplibre worker. The piece never falls back to a CDN. */
  workerUrl?: string
  maxZoom?: number
}

